final notifications = FlutterLocalNotificationsPlugin();
String uid() => DateTime.now().microsecondsSinceEpoch.toString();
String jDate(DateTime d) { final j = Gregorian.fromDateTime(d).toJalali(); return '${j.year}/${j.month.toString().padLeft(2, '0')}/${j.day.toString().padLeft(2, '0')}'; }
String hm(DateTime d) => '${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';
bool sameDay(DateTime a, DateTime b) => a.year == b.year && a.month == b.month && a.day == b.day;

class FollowUp { String id, text; DateTime at; DateTime? reminder; FollowUp({required this.id,required this.text,required this.at,this.reminder}); Map<String,dynamic> toJson()=>{'id':id,'text':text,'at':at.toIso8601String(),'reminder':reminder?.toIso8601String()}; factory FollowUp.fromJson(Map<String,dynamic> j)=>FollowUp(id:'${j['id']??uid()}',text:'${j['text']??''}',at:DateTime.tryParse('${j['at']}')??DateTime.now(),reminder:j['reminder']==null?null:DateTime.tryParse('${j['reminder']}')); }
class Item { String id,title,note,category; DateTime date; DateTime? reminder; bool task,archived,trash; List<String> tags,checklist; List<bool> checked; List<FollowUp> follows; Item({required this.id,required this.title,required this.note,required this.category,required this.date,required this.task,required this.tags,required this.checklist,required this.checked,required this.follows,this.reminder,this.archived=false,this.trash=false}); Map<String,dynamic> toJson()=>{'id':id,'title':title,'note':note,'category':category,'date':date.toIso8601String(),'reminder':reminder?.toIso8601String(),'task':task,'archived':archived,'trash':trash,'tags':tags,'checklist':checklist,'checked':checked,'follows':follows.map((e)=>e.toJson()).toList()}; factory Item.fromJson(Map<String,dynamic> j){final cl=List<String>.from(j['checklist']??[]);final ch=List<bool>.from(j['checked']??[]);while(ch.length<cl.length)ch.add(false);return Item(id:'${j['id']??uid()}',title:'${j['title']??''}',note:'${j['note']??''}',category:'${j['category']??'عمومی'}',date:DateTime.tryParse('${j['date']}')??DateTime.now(),reminder:j['reminder']==null?null:DateTime.tryParse('${j['reminder']}'),task:j['task']??false,archived:j['archived']??false,trash:j['trash']??false,tags:List<String>.from(j['tags']??[]),checklist:cl,checked:ch,follows:(j['follows']??j['followUps']??[]).map((e)=>FollowUp.fromJson(Map<String,dynamic>.from(e))).toList());}}

Future<void> initN() async { tz.initializeTimeZones(); tz.setLocalLocation(tz.getLocation('Asia/Tehran')); await notifications.initialize(const InitializationSettings(android: AndroidInitializationSettings('@mipmap/ic_launcher'))); await notifications.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission(); }
Future<void> remind(int id,String title,String body,DateTime when) async { if(!when.isAfter(DateTime.now()))return; const a=AndroidNotificationDetails('arvin','یادآوری آروین',channelDescription:'یادآوری',importance:Importance.max,priority:Priority.high); await notifications.zonedSchedule(id,title,body,tz.TZDateTime.from(when,tz.local),const NotificationDetails(android:a),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle); }
Future<DateTime?> pickJ(BuildContext c,DateTime initial,{bool allowPast=true}) async { final min=allowPast?Jalali(1380,1,1):Gregorian.fromDateTime(DateTime.now()).toJalali(); final p=await showJalaliDatePicker(c,initialDate:Gregorian.fromDateTime(initial).toJalali(),firstDate:min,lastDate:Jalali(1450,12,29),textDirection:TextDirection.rtl); if(p==null)return null; final g=p.toGregorian(); final t=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(initial)); if(t==null)return null; return DateTime(g.year,g.month,g.day,t.hour,t.minute); }

Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await initN(); runApp(const ArvinApp()); }
class ArvinApp extends StatefulWidget { const ArvinApp({super.key}); @override State<ArvinApp> createState()=>_AppState(); }
class _AppState extends State<ArvinApp>{String font='Vazirmatn';bool dark=false;@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState((){font=p.getString('font')??'Vazirmatn';dark=p.getBool('dark')??false;});}Future<void>setFont(String v)async{final p=await SharedPreferences.getInstance();await p.setString('font',v);if(mounted)setState(()=>font=v);}Future<void>setDark(bool v)async{final p=await SharedPreferences.getInstance();await p.setBool('dark',v);if(mounted)setState(()=>dark=v);}@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:font),darkTheme:ThemeData(useMaterial3:true,fontFamily:font,brightness:Brightness.dark),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(font:font,dark:dark,onFont:setFont,onDark:setDark)));}

class Home extends StatefulWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;const Home({super.key,required this.font,required this.dark,required this.onFont,required this.onDark});@override State<Home>createState()=>_HomeState();}
class _HomeState extends State<Home>{List<Item> items=[];List<String> cats=['عمومی'],tags=[];String cat='همه',status='همه',sort='آخرین وارده';bool rev=false,multi=false,loading=true;final sel=<String>{};String left='سطل زباله',right='امروز';
@override void initState(){super.initState();load();}
Future<void>load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('items');if(raw!=null)items=(jsonDecode(raw)as List).map((e)=>Item.fromJson(Map<String,dynamic>.from(e))).toList();cats=p.getStringList('cats')??['عمومی'];if(!cats.contains('عمومی'))cats.insert(0,'عمومی');tags=p.getStringList('tags')??[];cat=p.getString('cat')??'همه';status=p.getString('status')??'همه';sort=p.getString('sort')??'آخرین وارده';rev=p.getBool('rev')??false;left=p.getString('left')??'سطل زباله';right=p.getString('right')??'امروز';for(final x in items){if(x.reminder!=null)remind(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.reminder!);for(final f in x.follows){if(f.reminder!=null)remind(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text.isEmpty?'زمان پیگیری':f.text,f.reminder!);}}if(mounted)setState(()=>loading=false);}
Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('items',jsonEncode(items.map((e)=>e.toJson()).toList()));await p.setStringList('cats',cats);await p.setStringList('tags',tags);await p.setString('cat',cat);await p.setString('status',status);await p.setString('sort',sort);await p.setBool('rev',rev);await p.setString('left',left);await p.setString('right',right);}
List<Item>get shown{final now=DateTime.now();var r=items.where((x)=>!x.trash);r=r.where((x){if(status=='بایگانی')return x.archived;if(x.archived)return false;switch(status){case'امروز':return sameDay(x.date,now);case'آینده':return x.date.isAfter(now);case'عقب‌افتاده':return x.date.isBefore(now)&&!sameDay(x.date,now);case'یادداشت‌ها':return !x.task;case'کارها':return x.task;default:return true;}});r=r.where((x)=>cat=='همه'||x.category==cat);final l=r.toList();l.sort((a,b){int c;if(sort=='عنوان')c=a.title.compareTo(b.title);else if(sort=='تاریخ')c=a.date.compareTo(b.date);else{final ad=a.follows.isEmpty?a.date:a.follows.last.at;final bd=b.follows.isEmpty?b.date:b.follows.last.at;c=ad.compareTo(bd);}return rev?c:-c;});return l;}

Future<void>editItem({Item?old,bool task=false})async{final x=await showModalBottomSheet<Item>(context:context,isScrollControlled:true,builder:(_)=>Editor(old:old,task:old?.task??task,cats:cats));if(x==null)return;if(old==null)items.add(x);else items[items.indexWhere((e)=>e.id==old.id)]=x;await save();if(x.reminder!=null)await remind(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.reminder!);if(mounted)setState((){});}
Future<void>follow(Item x,{FollowUp?old})async{final f=await showDialog<FollowUp>(context:context,builder:(_)=>FollowEditor(old:old));if(f==null)return;if(old==null)x.follows.add(f);else x.follows[x.follows.indexOf(old)]=f;await save();if(f.reminder!=null)await remind(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text.isEmpty?'زمان پیگیری':f.text,f.reminder!);if(mounted)setState((){});}
Future<void>pdfItem(Item x)async{final d=pw.Document()..addPage(pw.MultiPage(build:(_)=>[pw.Text(x.title),pw.Text('دسته: ${x.category}'),pw.Text('تاریخ: ${jDate(x.date)} ${hm(x.date)}'),pw.Text(x.note),...x.follows.map((f)=>pw.Text('${jDate(f.at)} ${hm(f.at)} ${f.text}'))]));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_${x.id}.pdf');}
Future<void>pdfList()async{final d=pw.Document()..addPage(pw.MultiPage(build:(_)=>shown.map((x)=>pw.Text('${x.title} | ${x.category} | ${jDate(x.date)}')).toList()));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_list.pdf');}
Future<void>backup()async{final dir=await getApplicationDocumentsDirectory();final f=File('${dir.path}/arvin_backup.json');await f.writeAsString(jsonEncode({'items':items.map((e)=>e.toJson()).toList(),'cats':cats,'tags':tags}));await Share.shareXFiles([XFile(f.path)],text:'پشتیبان آروین');}
Future<void>restore()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(r==null||r.files.single.bytes==null)return;final m=jsonDecode(utf8.decode(r.files.single.bytes!));items=(m['items']as List).map((e)=>Item.fromJson(Map<String,dynamic>.from(e))).toList();cats=List<String>.from(m['cats']??['عمومی']);tags=List<String>.from(m['tags']??[]);if(!cats.contains('عمومی'))cats.insert(0,'عمومی');await save();if(mounted)setState((){});}
Future<void>manage(String title,List<String> source,bool isCat)async{final out=await showDialog<List<String>>(context:context,builder:(_)=>ManageDialog(title,source,isCat));if(out!=null){if(isCat)cats=out;else tags=out;await save();if(mounted)setState((){});}}
Future<void>swipe(Item x,String a)async{switch(a){case'امروز':x.date=DateTime.now();break;case'بایگانی':x.archived=true;break;case'سطل زباله':x.trash=true;break;case'پیگیری':if(x.task)await follow(x);break;case'ویرایش':await editItem(old:x);break;case'اشتراک‌گذاری':await pdfItem(x);break;}await save();if(mounted)setState((){});}
Future<void>settings()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>Settings(font:widget.font,dark:widget.dark,onFont:widget.onFont,onDark:widget.onDark,left:left,right:right,onSwipe:(l,r)async{left=l;right=r;await save();setState((){});})));}
void details(Item x){Navigator.push(context,MaterialPageRoute(builder:(_)=>Details(item:x,onEdit:()=>editItem(old:x),onFollow:()=>follow(x),onEditFollow:(f)=>follow(x,old:f),onDeleteFollow:(f)async{x.follows.remove(f);await save();},onChanged:save)));}
Future<void>search()async{final c=TextEditingController();final q=await showDialog<String>(context:context,builder:(d)=>AlertDialog(title:const Text('جستجو'),content:TextField(controller:c,autofocus:true),actions:[FilledButton(onPressed:()=>Navigator.pop(d,c.text),child:const Text('جستجو'))]));if(q==null||q.trim().isEmpty)return;final s=q.toLowerCase();final r=items.where((x)=>('${x.title} ${x.note} ${x.category} ${x.tags.join(' ')} ${x.follows.map((f)=>f.text).join(' ')}').toLowerCase().contains(s)).toList();if(!mounted)return;showDialog(context:context,builder:(d)=>AlertDialog(title:const Text('نتایج'),content:SizedBox(width:340,height:350,child:ListView(children:r.map((x)=>ListTile(title:Text(x.title),onTap:(){Navigator.pop(d);details(x);})).toList()))));}
Future<void>trashPage()async{await showDialog(context:context,builder:(d){final tr=items.where((x)=>x.trash).toList();return AlertDialog(title:const Text('سطل زباله'),content:SizedBox(width:350,height:320,child:tr.isEmpty?const Center(child:Text('سطل زباله خالی است')):ListView(children:tr.map((x)=>ListTile(title:Text(x.title),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(icon:const Icon(Icons.restore),onPressed:()async{x.trash=false;await save();Navigator.pop(d);setState((){});}),IconButton(icon:const Icon(Icons.delete_forever),onPressed:()async{items.remove(x);await save();Navigator.pop(d);setState((){});})]))).toList())),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('بستن'))]);});}
@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(endDrawer:Drawer(child:SafeArea(child:ListView(children:[const DrawerHeader(child:Text('آروین',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold))),...['همه','امروز','آینده','عقب‌افتاده','یادداشت‌ها','کارها','بایگانی'].map((v)=>ListTile(title:Text(v),onTap:(){status=v;save();Navigator.pop(c);setState((){});})),ListTile(title:const Text('دسته‌بندی‌ها'),onTap:(){Navigator.pop(c);manage('دسته‌بندی‌ها',cats,true);}),ListTile(title:const Text('تگ‌ها'),onTap:(){Navigator.pop(c);manage('تگ‌ها',tags,false);}),ListTile(title:const Text('سطل زباله'),onTap:(){Navigator.pop(c);trashPage();}),ListTile(title:const Text('خروجی PDF لیست'),onTap:(){Navigator.pop(c);pdfList();}),ListTile(title:const Text('پشتیبان‌گیری'),onTap:(){Navigator.pop(c);backup();}),ListTile(title:const Text('بازیابی'),onTap:(){Navigator.pop(c);restore();}),ListTile(title:const Text('تنظیمات'),onTap:(){Navigator.pop(c);settings();})]))),appBar:AppBar(title:const Text('آروین'),actions:[IconButton(icon:const Icon(Icons.search),onPressed:search),Builder(builder:(b)=>IconButton(icon:const Icon(Icons.menu),onPressed:()=>Scaffold.of(b).openEndDrawer()))]),body:Column(children:[Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:DropdownButtonFormField<String>(initialValue:cat,items:['همه',...cats].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),decoration:const InputDecoration(labelText:'دسته‌بندی'),onChanged:(v){if(v!=null){cat=v;save();setState((){});}})),const SizedBox(width:8),Expanded(child:DropdownButtonFormField<String>(initialValue:status,items:const['همه','امروز','آینده','عقب‌افتاده','یادداشت‌ها','کارها','بایگانی'].map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),decoration:const InputDecoration(labelText:'وضعیت'),onChanged:(v){if(v!=null){status=v;save();setState((){});}}))])),Expanded(child:shown.isEmpty?const Center(child:Text('موردی وجود ندارد')):ListView.builder(itemCount:shown.length,itemBuilder:(ctx,i){final x=shown[i];final last=x.follows.isEmpty?null:x.follows.last;return Dismissible(key:ValueKey(x.id),background:Container(alignment:Alignment.centerRight,padding:const EdgeInsets.all(20),child:Text(right)),secondaryBackground:Container(alignment:Alignment.centerLeft,padding:const EdgeInsets.all(20),child:Text(left)),confirmDismiss:(dir)async{await swipe(x,dir==DismissDirection.startToEnd?right:left);return x.trash||x.archived;},child:Card(child:ListTile(onLongPress:(){multi=true;sel.add(x.id);setState((){});},onTap:(){if(multi){if(sel.contains(x.id))sel.remove(x.id);else sel.add(x.id);if(sel.isEmpty)multi=false;setState((){});}else{details(x);}},leading:CircleAvatar(child:Icon(x.task?Icons.task_alt:Icons.note_outlined)),title:Text(x.title.isEmpty?'بدون عنوان':x.title),subtitle:Text('${x.category} • ${jDate(x.date)} ${hm(x.date)}\n${last==null?'بدون پیگیری':'آخرین پیگیری ${jDate(last.at)} ${hm(last.at)}'}'),trailing:x.task?IconButton(icon:const Icon(Icons.add_task),onPressed:()=>follow(x)):null)));}))]),floatingActionButton:multi?FloatingActionButton.extended(onPressed:()async{for(final id in sel){final x=items.firstWhere((e)=>e.id==id);x.archived=true;}sel.clear();multi=false;await save();setState((){});},label:const Text('بایگانی انتخاب‌شده‌ها'),icon:const Icon(Icons.archive)):FloatingActionButton(onPressed:()=>editItem(task:false),child:const Icon(Icons.add)));}}

