class _EditorState extends State<Editor>{late TextEditingController title,note,tagsCtl,checkCtl;late String cat;late bool task;late DateTime date;DateTime?rem;bool manual=false;@override void initState(){super.initState();final x=widget.old;title=TextEditingController(text:x?.title??'');note=TextEditingController(text:x?.note??'');tagsCtl=TextEditingController(text:x?.tags.join(', ')??'');checkCtl=TextEditingController(text:x?.checklist.join('\n')??'');cat=x?.category??widget.cats.first;task=x?.task??widget.task;date=x?.date??DateTime.now();rem=x?.reminder;title.addListener(()=>manual=title.text.trim().isNotEmpty);}String auto(){final v=note.text.split('\n').map((e)=>e.trim()).firstWhere((e)=>e.isNotEmpty,orElse:()=> '');return v.length>80?v.substring(0,80):v;}@override Widget build(BuildContext c)=>SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(c).viewInsets.bottom),child:SingleChildScrollView(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:title,decoration:const InputDecoration(labelText:'عنوان')),TextField(controller:note,maxLines:6,onChanged:(_){if(!manual&&title.text.trim().isEmpty){final s=auto();if(s.isNotEmpty)title.text=s;}},decoration:const InputDecoration(labelText:'توضیحات / یادداشت')),SwitchListTile(title:const Text('فعال بودن پیگیری'),value:task,onChanged:(v)=>setState(()=>task=v)),DropdownButtonFormField<String>(initialValue:cat,items:widget.cats.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),decoration:const InputDecoration(labelText:'دسته‌بندی'),onChanged:(v){if(v!=null)setState(()=>cat=v);}),TextField(controller:tagsCtl,decoration:const InputDecoration(labelText:'تگ‌ها با ویرگول')),TextField(controller:checkCtl,maxLines:3,decoration:const InputDecoration(labelText:'چک‌لیست؛ هر مورد یک سطر')),ListTile(title:Text('تاریخ: ${jDate(date)} ${hm(date)}'),onTap:()async{final d=await pickJ(c,date,allowPast:true);if(d!=null)setState(()=>date=d);}),ListTile(title:Text(rem==null?'یادآوری ندارد':'یادآوری: ${jDate(rem!)} ${hm(rem!)}'),onTap:()async{final d=await pickJ(c,rem??DateTime.now().add(const Duration(minutes:5)),allowPast:false);if(d!=null)setState(()=>rem=d);}),FilledButton(onPressed:(){final o=widget.old;final lines=checkCtl.text.split('\n').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList();Navigator.pop(c,Item(id:o?.id??uid(),title:title.text.trim().isEmpty?auto():title.text.trim(),note:note.text.trim(),category:cat,date:date,reminder:rem,task:task,tags:tagsCtl.text.split(',').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList(),checklist:lines,checked:List<bool>.generate(lines.length,(i)=>i<(o?.checked.length??0)?o!.checked[i]:false),follows:List<FollowUp>.from(o?.follows??[]),archived:o?.archived??false,trash:o?.trash??false));},child:const Text('ذخیره'))])));}}

