class Details extends StatelessWidget{final Item item;final Future<void>Function()onEdit,onFollow;final Future<void>Function(FollowUp)onEditFollow,onDeleteFollow;final Future<void>Function()onChanged;const Details({super.key,required this.item,required this.onEdit,required this.onFollow,required this.onEditFollow,required this.onDeleteFollow,required this.onChanged});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(item.title.isEmpty?'بدون عنوان':item.title),actions:[IconButton(icon:const Icon(Icons.edit),onPressed:onEdit)]),body:ListView(padding:const EdgeInsets.all(16),children:[Text(item.note.isEmpty?'بدون توضیحات':item.note,style:const TextStyle(fontSize:18)),const SizedBox(height:12),Text('تاریخ: ${jDate(item.date)} ${hm(item.date)}'),Text('دسته: ${item.category}'),if(item.tags.isNotEmpty)Wrap(spacing:6,children:item.tags.map((e)=>Chip(label:Text(e))).toList()),if(item.checklist.isNotEmpty)...[const Divider(),const Text('چک‌لیست'),...List.generate(item.checklist.length,(i)=>CheckboxListTile(value:item.checked[i],onChanged:(v){item.checked[i]=v??false;onChanged();},title:Text(item.checklist[i])))],if(item.task)...[const Divider(),Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('سوابق پیگیری'),FilledButton.icon(onPressed:onFollow,icon:const Icon(Icons.add),label:const Text('پیگیری جدید'))]),...item.follows.reversed.map((f)=>Card(child:ListTile(title:Text(f.text.isEmpty?'(بدون شرح)':f.text),subtitle:Text('${jDate(f.at)} ${hm(f.at)}'),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='edit')await onEditFollow(f);else await onDeleteFollow(f);onChanged();},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('ویرایش')),PopupMenuItem(value:'delete',child:Text('حذف'))])))).toList()]]));}

class ManageDialog extends StatefulWidget{final String title;final List<String>src;final bool isCat;const ManageDialog(this.title,this.src,this.isCat,{super.key});@override State<ManageDialog>createState()=>_ManageState();}
class _ManageState extends State<ManageDialog>{late List<String>list;final ctl=TextEditingController();@override void initState(){super.initState();list=[...widget.src];}@override Widget build(BuildContext c)=>AlertDialog(title:Text(widget.title),content:SizedBox(width:330,height:330,child:Column(children:[TextField(controller:ctl,decoration:InputDecoration(labelText:'مورد جدید',suffixIcon:IconButton(icon:const Icon(Icons.add),onPressed:(){final v=ctl.text.trim();if(v.isNotEmpty&&!list.contains(v)){setState(()=>list.add(v));ctl.clear();}}))),Expanded(child:ListView(children:list.map((v)=>ListTile(title:Text(v),trailing:widget.isCat&&v=='عمومی'?null:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>setState(()=>list.remove(v)))).toList()))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('لغو')),FilledButton(onPressed:()=>Navigator.pop(c,list),child:const Text('ذخیره'))]);}

class Settings extends StatelessWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;final String left,right;final Future<void>Function(String,String)onSwipe;const Settings({super.key,required this.font,required this.dark,required this.onFont,required this.onDark,required this.left,required this.right,required this.onSwipe});Future<String?>pick(BuildContext c)=>showDialog<String>(context:c,builder:(d)=>SimpleDialog(title:const Text('عملیات Swipe'),children:['هیچ‌کاری','امروز','بایگانی','سطل زباله','پیگیری','ویرایش','اشتراک‌گذاری'].map((e)=>SimpleDialogOption(onPressed:()=>Navigator.pop(d,e),child:Text(e))).toList()));@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تنظیمات')),body:ListView(padding:const EdgeInsets.all(16),children:[SwitchListTile(title:const Text('حالت تاریک'),value:dark,onChanged:onDark),DropdownButtonFormField<String>(initialValue:font,items:const[DropdownMenuItem(value:'Vazirmatn',child:Text('Vazirmatn'))],onChanged:(v){if(v!=null)onFont(v);},decoration:const InputDecoration(labelText:'فونت')),ListTile(title:Text('کشیدن به راست: $right'),onTap:()async{final v=await pick(c);if(v!=null)onSwipe(left,v);}),ListTile(title:Text('کشیدن به چپ: $left'),onTap:()async{final v=await pick(c);if(v!=null)onSwipe(v,right);})]));}
